const xml = $json.data || '';
const primary = $('2. Set Config').first().json.sitemapUrl;
const isIndex = /<sitemapindex[\s>]/i.test(xml);
const out = [];
if (isIndex) {
  const re = /<loc>\s*([^<]+?)\s*<\/loc>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    out.push({ json: { sitemapUrl: m[1].trim() } });
  }
}
if (out.length === 0) {
  out.push({ json: { sitemapUrl: primary } });
}
return out;

const cfg = $('2. Set Config').first().json;
const maxPages = Number(cfg.maxPages) || 50;
const all = $input.all();
const seen = new Set();
const out = [];
for (const it of all) {
  const xml = (it.json && it.json.data) ? it.json.data : '';
  const re = /<loc>\s*([^<]+?)\s*<\/loc>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    let u = m[1].trim();
    if (!u) continue;
    if (/\.xml($|\?)/i.test(u)) continue;
    if (/sitemap/i.test(u)) continue;
    if (seen.has(u)) continue;
    seen.add(u);
    let section = 'Pages';
    try {
      const parts = new URL(u).pathname.split('/').filter(Boolean);
      if (parts.length > 1) section = parts[0];
    } catch (e) {}
    out.push({ json: { url: u, section } });
    if (out.length >= maxPages) break;
  }
  if (out.length >= maxPages) break;
}
return out;

const cfg = $('2. Set Config').first().json;
const siteName = cfg.siteName || 'My Website';
const siteDescription = cfg.siteDescription || '';
const pages = $('6. Extract Page URLs').all();
const htmls = $input.all();

function decode(s) {
  return String(s)
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function titleFromSlug(u) {
  try {
    const parts = new URL(u).pathname.split('/').filter(Boolean);
    const slug = parts.length ? parts[parts.length - 1] : u;
    const clean = slug.replace(/\.[a-z]+$/i, '').replace(/[-_]+/g, ' ').trim();
    if (!clean) return siteName + ' home';
    return clean.replace(/\b\w/g, c => c.toUpperCase());
  } catch (e) { return u; }
}

const sections = {};
const order = [];
for (let i = 0; i < pages.length; i++) {
  const url = pages[i].json.url;
  const section = pages[i].json.section || 'Pages';
  const html = (htmls[i] && htmls[i].json && htmls[i].json.data) ? htmls[i].json.data : '';
  let title = '';
  let desc = '';
  if (html) {
    const t = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
    if (t) title = decode(t[1]);
    let d = html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([\s\S]*?)["']/i);
    if (!d) d = html.match(/<meta[^>]+content=["']([\s\S]*?)["'][^>]+name=["']description["']/i);
    if (d) desc = decode(d[1]);
  }
  if (!title) title = titleFromSlug(url);
  if (!sections[section]) { sections[section] = []; order.push(section); }
  let line = '- [' + title + '](' + url + ')';
  if (desc) line += ': ' + desc;
  sections[section].push(line);
}

let out = '# ' + siteName + '\n';
if (siteDescription) out += '\n> ' + siteDescription + '\n';
out += '\n';
const names = order.sort();
for (const s of names) {
  const heading = s.charAt(0).toUpperCase() + s.slice(1);
  out += '## ' + heading + '\n';
  for (const line of sections[s]) out += line + '\n';
  out += '\n';
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pageCount = pages.length;

const pageHtml = `
<style>
  .llmswrap { max-width: 760px; margin: 0 auto; text-align: left; font-family: system-ui, -apple-system, Roboto, Arial, sans-serif; color: #0f172a; }
  .llmswrap .badge { display: inline-block; font-size: 12px; font-weight: 600; color: #4338ca; background: #eef2ff; border: 1px solid #e0e7ff; padding: 3px 10px; border-radius: 999px; margin-bottom: 12px; }
  .llmswrap .title { font-size: 22px; font-weight: 700; margin: 0 0 4px; }
  .llmswrap .sub { font-size: 14px; color: #64748b; margin: 0 0 16px; line-height: 1.5; }
  .llmswrap textarea { width: 100%; box-sizing: border-box; min-height: 340px; resize: vertical; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 13px; line-height: 1.55; padding: 16px; color: #e6edf3; background: #0d1117; border: 1px solid #30363d; border-radius: 12px; outline: none; }
  .llmswrap textarea:focus { border-color: #6366f1; box-shadow: 0 0 0 3px rgba(99,102,241,0.25); }
  .llmswrap .row { display: flex; gap: 12px; margin-top: 16px; flex-wrap: wrap; }
  .llmswrap .btn { flex: 1 1 auto; min-width: 160px; font-size: 15px; font-weight: 600; padding: 13px 18px; border-radius: 12px; border: 0; cursor: pointer; transition: transform .16s ease, box-shadow .16s ease, background .16s ease; }
  .llmswrap .btn:hover { transform: translateY(-1px); }
  .llmswrap .btn:active { transform: translateY(0) scale(.98); }
  .llmswrap .primary { color: #fff; background: linear-gradient(135deg, #6366f1, #8b5cf6); box-shadow: 0 6px 18px rgba(99,102,241,0.35); }
  .llmswrap .primary.ok { background: linear-gradient(135deg, #16a34a, #22c55e); animation: llmspop .32s ease; }
  .llmswrap .ghost { color: #0f172a; background: #fff; border: 1px solid #cbd5e1; box-shadow: 0 2px 8px rgba(15,23,42,0.06); }
  .llmswrap .ghost:hover { border-color: #6366f1; color: #4338ca; }
  @keyframes llmspop { 0% { transform: scale(1); } 45% { transform: scale(1.06); } 100% { transform: scale(1); } }
  @media (max-width: 520px) { .llmswrap .btn { flex-basis: 100%; } }
</style>
<div class='llmswrap'>
  <div class='badge'>${pageCount} pages mapped</div>
  <div class='title'>Your llms.txt is ready</div>
  <div class='sub'>Review it below, then copy or download. Upload the file to your site root at yourdomain.com/llms.txt</div>
  <textarea id='llmsOut' readonly spellcheck='false'>${esc(out)}</textarea>
  <div class='row'>
    <button id='llmsCopy' type='button' class='btn primary'>Copy to clipboard</button>
    <button id='llmsDl' type='button' class='btn ghost'>Download llms.txt</button>
  </div>
</div>
<script>
  (function () {
    var out = document.getElementById('llmsOut');
    var copy = document.getElementById('llmsCopy');
    var dl = document.getElementById('llmsDl');
    var reset;
    copy.addEventListener('click', function () {
      var done = function () {
        copy.classList.add('ok');
        copy.textContent = 'Copied';
        clearTimeout(reset);
        reset = setTimeout(function () { copy.classList.remove('ok'); copy.textContent = 'Copy to clipboard'; }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(out.value).then(done, function () { out.select(); document.execCommand('copy'); done(); });
      } else {
        out.select(); document.execCommand('copy'); done();
      }
    });
    dl.addEventListener('click', function () {
      var blob = new Blob([out.value], { type: 'text/plain;charset=utf-8' });
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'llms.txt';
      document.body.appendChild(a);
      a.click();
      setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
    });
  })();
</script>`;

return [{ json: { pageCount: pageCount, fileName: 'llms.txt', content: out, pageHtml: pageHtml } }];
